+function isNativeQuitAccelerator(accelerator: string): boolean {
+	const parsed = parseAccelerator(accelerator);
+	return (
+		isMacPlatform() &&
+		parsed !== null &&
+		parsed.mod &&
+		!parsed.ctrl &&
+		!parsed.alt &&
+		!parsed.shift &&
+		parsed.key === "q"
+	);
